-- Function: public.fn_get_portfolio_journey_entries
-- Backup generated on 2026-10-25 20:33:40

CREATE OR REPLACE FUNCTION public.fn_get_portfolio_journey_entries(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, observation_date timestamp with time zone, journey_type character varying, title character varying, observation text, child_voice text, teacher_reflection text, is_milestone boolean, is_parent_visible boolean, parent_visibility_status character varying, teacher_name character varying)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT je.id, je.observation_date, je.journey_type::VARCHAR,            je.title::VARCHAR, je.observation, je.child_voice,            je.teacher_reflection, je.is_milestone,            je.is_parent_visible, je.parent_visibility_status::VARCHAR,            COALESCE(t.first_name || ' ' || t.last_name, 'Teacher')::VARCHAR AS teacher_name     FROM child_journey_entries je     LEFT JOIN teachers t ON je.teacher_id = t.id     WHERE je.tenant_id = p_tenant_id AND je.child_id = p_child_id     ORDER BY je.observation_date DESC; END; $function$ ;
